27	        expression = "java(owner.getLastName() + \", \" + owner.getFirstName())")
28	    @Mapping(target = "initials", expression = "java(initials(owner))")
29	    @Mapping(target = "checkDigit", expression = "java(checkDigit(owner))")
30	    @Mapping(target = "membershipNumber", expression = "java(membershipNumber(owner))")
31	    @Mapping(target = "membershipLevel", expression = "java(membershipLevel(owner))")
32	    @Mapping(target = "locality", expression = "java(locality(owner))")
33	    @Mapping(target = "contactPreference", expression = "java(contactPreference(owner))")
34	    @Mapping(target = "identityKey", expression = "java(identityKey(owner))")
35	    @Mapping(target = "ageBand", expression = "java(ageBand(owner))")
36	    OwnerDto toOwnerDto(Owner owner);
37	
38	    /**
39	     * The upper-cased first letters of the first and last name, dot-separated with a
40	     * trailing dot, e.g. {@code J.S.}.
41	     */
42	    default String initials(Owner owner) {
43	        return Character.toUpperCase(owner.getFirstName().charAt(0)) + "."
44	            + Character.toUpperCase(owner.getLastName().charAt(0)) + ".";
45	    }
46	
47	    /**
48	     * The Luhn check digit computed over the digits of the owner's customer code.
49	     */
50	    default int checkDigit(Owner owner) {
51	        return Luhn.checkDigit(owner.getCustomerCode());
52	    }
53	
54	    /**
55	     * The owner's membership number, formatted as {@code <customerCode>-M<YY>} where
56	     * {@code YY} is the last two digits of the registration date year, e.g.
57	     * {@code SMI-0007-M26}.
